mapper.select:
select apt_cmplex_no
from mgmt_office
where mgmt_ofc_no = #{mgmtOfcNo}

select fc.cont_no , fc.facility_no , fc.partner_no , fc.cont_nm , fc.bid_ty_cd , fc.cont_dt , fc.cont_stts_cd , fc.cont_amt , fc.pymt_dt , fc.cont_bgng_dt , fc.cont_end_dt , f.facility_nm , fac_ty.code_name as facility_ty_nm , p.partner_nm , bid_ty.code_name as bid_ty_nm , cont_stts.code_name as cont_stts_nm , trunc(fc.cont_end_dt) - trunc(sysdate) as expire_days , case when up.utility_provider_no is null then 'N' else 'Y' end as meter_setting_yn , up.utility_provider_no , up.csv_idntf_key , up.ext_cust_no , up.rmrk_cn as utility_rmrk_cn from facility_contract fc inner join facility f on fc.facility_no = f.facility_no inner join partner p on fc.partner_no = p.partner_no left outer join common_code fac_ty on f.facility_ty_cd = fac_ty.code_no_cd and fac_ty.group_code_no = 'FACILITY_TY' left outer join common_code bid_ty on fc.bid_ty_cd = bid_ty.code_no_cd and bid_ty.group_code_no = 'BID_TY' left outer join common_code cont_stts on fc.cont_stts_cd = cont_stts.code_no_cd and cont_stts.group_code_no = 'CONT_STTS' left outer join utility_provider up on fc.cont_no = up.cont_no where f.apt_cmplex_no = #{aptCmplexNo}
and fc.cont_stts_cd = #{contSttsCd}
and fc.bid_ty_cd = #{bidTyCd}
and trunc(fc.cont_end_dt) - trunc(sysdate) between 0 and 7
and up.utility_provider_no is not null
and up.utility_provider_no is null
and ( upper(fc.cont_no) like '%' || upper(#{keyword}) || '%' or upper(fc.cont_nm) like '%' || upper(#{keyword}) || '%' or upper(f.facility_nm) like '%' || upper(#{keyword}) || '%' or upper(p.partner_nm) like '%' || upper(#{keyword}) || '%' )
order by fc.cont_end_dt asc nulls last , fc.cont_no desc

mapper.insert:

    select 'CONT' || lpad(nvl(max(to_number(regexp_substr(cont_no, '[0-9]+'))), 0) + 1, 4, '0')
    from facility_contract

insert into facility_contract (
cont_no
, facility_no
, partner_no
, cont_nm
, bid_ty_cd
, cont_dt
, cont_stts_cd
, cont_amt
, pymt_dt
, cont_bgng_dt
, cont_end_dt
) values (
#{contNo}
, #{facilityNo}
, #{partnerNo}
, #{contNm}
, #{bidTyCd}
, #{contDt}
, #{contSttsCd}
, #{contAmt}
, #{pymtDt}
, #{contBgngDt}
, #{contEndDt}
)

mapper.update:
update facility_contract
set facility_no    = #{facilityNo}
, partner_no     = #{partnerNo}
, cont_nm        = #{contNm}
, bid_ty_cd      = #{bidTyCd}
, cont_dt        = #{contDt}
, cont_stts_cd   = #{contSttsCd}
, cont_amt       = #{contAmt}
, pymt_dt        = #{pymtDt}
, cont_bgng_dt   = #{contBgngDt}
, cont_end_dt    = #{contEndDt}
where cont_no = #{contNo}

mapper.insert:

    select 'UP' || lpad(nvl(max(to_number(regexp_substr(utility_provider_no, '[0-9]+'))), 0) + 1, 6, '0')
    from utility_provider

insert into utility_provider (
utility_provider_no
, apt_cmplex_no
, partner_no
, cont_no
, csv_idntf_key
, ext_cust_no
, rmrk_cn
) values (
#{utilityProviderNo}
, #{aptCmplexNo}
, #{partnerNo}
, #{contNo}
, #{csvIdntfKey}
, #{extCustNo}
, #{utilityRmrkCn}
)

mapper.update:
update utility_provider
set csv_idntf_key = #{csvIdntfKey}
, ext_cust_no   = #{extCustNo}
, rmrk_cn       = #{utilityRmrkCn}
where utility_provider_no = #{utilityProviderNo}
and cont_no = #{contNo}
